f['Test.java']="""import java.io.*;import java.util.*;import org.bukkit.*;import org.bukkit.entity.*;import ru.rooyzee.elytrixairdrop.*;import ru.rooyzee.elytrixairdrop.patch.*;public class Test{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{World w=new World();Bukkit.world=w;Main p=new Main();p.dir=new File(args[0]);Location floor=new Location(w,0,64,0),block=new Location(w,0,65,0),obstacle=new Location(w,0,66,0);w.blocks.put(floor,Material.STONE);w.blocks.put(obstacle,Material.CHEST);Player a=new Player(),b=new Player(),outside=new Player();a.w=b.w=outside.w=w;FireWall wa=FireWall.start(p,w,List.of(floor),a);ok(w.displays.size()==5&&a.shown.size()==5&&b.shown.isEmpty()&&outside.shown.isEmpty(),"only entrant shown animation");ok(w.displays.stream().noneMatch(d->d.visible),"hidden by default");double initial=w.displays.get(0).l.getY();for(int i=0;i<4;i++)wa.tick();ok(w.displays.get(0).l.getY()>initial,"animation moves");for(int i=0;i<24;i++)wa.tick();ok(a.blocks.get(block)==Material.STONE&&b.blocks.isEmpty()&&outside.blocks.isEmpty(),"fake blocks private");ok(block.getBlock().getType()==Material.AIR&&obstacle.getBlock().getType()==Material.CHEST,"world unchanged");FireWall wb=FireWall.start(p,w,List.of(floor),b);for(int i=0;i<24;i++)wb.tick();ok(b.blocks.get(block)==Material.STONE&&outside.blocks.isEmpty(),"second entrant sees own blocks");wa.close();ok(a.blocks.get(block)==Material.AIR&&b.blocks.get(block)==Material.STONE,"releasing one keeps other locked visually");wb.close();ok(b.blocks.get(block)==Material.AIR,"individual cleanup");File file=new File(p.dir,"fire-wall-recovery.bin");w.blocks.put(block,Material.STONE);try(DataOutputStream out=new DataOutputStream(new FileOutputStream(file))){out.writeUTF("ELYTRIX_FIRE_WALL_1");out.writeUTF("test");out.writeInt(1);out.writeInt(0);out.writeInt(65);out.writeInt(0);out.writeUTF("AIR");out.writeUTF("STONE");}FireWall.recover(p);ok(block.getBlock().getType()==Material.AIR&&!file.exists(),"legacy crash recovery");System.out.println("Independent private wall animation, client blocks, cleanup and legacy recovery OK");}}"""

